package lk.gov.health.govcare.workflow;
import lk.gov.health.govcare.common.SqlSupport;import lk.gov.health.govcare.security.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/doctor-command-center") public class DoctorCommandCenterController{private final SqlSupport sql;private final CurrentUser current;private final LaboratoryService lab;private final RadiologyService rad;private final PrescriptionService rx;private final AppointmentService ap;public DoctorCommandCenterController(SqlSupport sql,CurrentUser current,LaboratoryService lab,RadiologyService rad,PrescriptionService rx,AppointmentService ap){this.sql=sql;this.current=current;this.lab=lab;this.rad=rad;this.rx=rx;this.ap=ap;}
@GetMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','HOSPITAL_ADMIN','DOCTOR')")public Map<String,Object> data(){GovCarePrincipal a=current.get();boolean doctor=a.role().equals("doctor");Map<String,Object>p=new HashMap<>();p.put("hospital",a.hospitalId());p.put("doctor",a.id());p.put("filter",doctor);Map<String,Object>stats=sql.required("select (select count(*) from opd_queue q where q.hospital_id=:hospital and q.queue_status='waiting' and(:filter=false or q.doctor_id=:doctor or q.doctor_id is null))::int waiting,(select count(*) from opd_queue q where q.hospital_id=:hospital and q.queue_status='called' and(:filter=false or q.doctor_id=:doctor))::int called,(select count(*) from opd_queue q where q.hospital_id=:hospital and q.queue_status in('checking','in-consultation') and(:filter=false or q.doctor_id=:doctor))::int checking,(select count(*) from opd_queue q where q.hospital_id=:hospital and q.queue_status='completed' and q.completed_at::date=current_date and(:filter=false or q.doctor_id=:doctor))::int completed_today,(select count(*) from appointments x where x.hospital_id=:hospital and x.scheduled_at::date=current_date and(:filter=false or x.doctor_id=:doctor or x.doctor_id is null))::int appointments_today,(select count(*) from lab_requests x where x.hospital_id=:hospital and(:filter=false or x.requested_by=:doctor) and x.workflow_status='released' and x.reviewed_at is null)::int pending_lab_review,(select count(*) from radiology_requests x where x.hospital_id=:hospital and(:filter=false or x.requested_by=:doctor) and x.workflow_status='released' and x.reviewed_at is null)::int pending_radiology_review,(select count(*) from prescriptions x where x.hospital_id=:hospital and(:filter=false or x.doctor_id=:doctor) and x.workflow_status in('sent_to_pharmacy','verified','partially_dispensed'))::int pharmacy_pending",p,"Unable to load command center.");String q=WorkflowSql.QUEUE_SELECT+" where q.hospital_id=:hospital and q.queue_status in('waiting','called','checking','in-consultation','paused')"+(doctor?" and(q.doctor_id is null or q.doctor_id=:doctor or(:department is not null and q.department_id=:department))":"")+" order by case q.queue_status when 'checking' then 0 when 'called' then 1 else 2 end,q.created_at limit 100";p.put("department",a.departmentId());List<Map<String,Object>>queue=sql.list(q,p);List<Map<String,Object>>appointments=ap.list(a,null,null,null).stream().filter(x->String.valueOf(x.get("scheduled_at")).startsWith(java.time.LocalDate.now().toString())).limit(100).toList();List<Map<String,Object>>labs=lab.list(a,"released",null).stream().filter(x->!doctor||Objects.equals(String.valueOf(x.get("requested_by_name")),a.fullName())).toList();List<Map<String,Object>>rads=rad.list(a,"released",null).stream().filter(x->!doctor||Objects.equals(String.valueOf(x.get("requested_by_name")),a.fullName())).toList();List<Map<String,Object>>prescriptions=rx.list(a,null,null,null).stream().filter(x->Set.of("sent_to_pharmacy","verified","partially_dispensed").contains(String.valueOf(x.get("workflow_status")))).toList();return Map.of("stats",stats,"queue",queue,"appointments",appointments,"pendingLabResults",labs,"pendingRadiologyReports",rads,"pharmacyPrescriptions",prescriptions);}}
